import { readFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { resolve } from "node:path";
import satori from "satori";
import sharp from "sharp";

// Public path of a page's preview image, generated by src/pages/og/.
export const ogImagePath = (lang: string, postId?: string) =>
  `/og/${lang}/${postId ?? "default"}.png`;

export const OG_WIDTH = 1200;
export const OG_HEIGHT = 630;

const require = createRequire(import.meta.url);
const font = (weight: 400 | 600) =>
  readFile(
    require.resolve(
      `@fontsource/ibm-plex-sans/files/ibm-plex-sans-latin-${weight}-normal.woff`,
    ),
  );

let assets: Promise<{ regular: Buffer; bold: Buffer; avatar: string }>;
function loadAssets() {
  assets ??= Promise.all([
    font(400),
    font(600),
    sharp(resolve("src/assets/avatar.jpg")).resize(144, 144).png().toBuffer(),
  ]).then(([regular, bold, avatar]) => ({
    regular,
    bold,
    avatar: `data:image/png;base64,${avatar.toString("base64")}`,
  }));
  return assets;
}

type Node = {
  type: string;
  props: {
    style?: Record<string, unknown>;
    children?: unknown;
    src?: string;
    width?: number;
    height?: number;
  };
};
const el = (
  type: string,
  style: Record<string, unknown>,
  children?: unknown,
): Node => ({ type, props: { style, children } });

export type OgContent = {
  eyebrow: string;
  title: string;
  description: string;
  author: string;
  role: string;
};

// Social preview image shared by Open Graph, X/Twitter, and structured data.
export async function renderOgImage(content: OgContent) {
  const { regular, bold, avatar } = await loadAssets();
  const titleSize = content.title.length > 60 ? 54 : 64;
  // Satori sizes boxes like content-box, so subtract padding and border.
  const textWidth = OG_WIDTH - 16 - 160;
  const contentHeight = OG_HEIGHT - 144;
  const tree = el(
    "div",
    {
      width: textWidth,
      height: contentHeight,
      display: "flex",
      flexDirection: "column",
      justifyContent: "space-between",
      padding: "72px 80px",
      background: "#17191c",
      borderLeft: "16px solid #8daac7",
      color: "#dcdfe3",
      fontFamily: "IBM Plex Sans",
    },
    [
      el("div", { display: "flex", flexDirection: "column", gap: 24 }, [
        el(
          "div",
          {
            display: "flex",
            alignSelf: "flex-start",
            padding: "6px 18px",
            border: "2px solid #3b4048",
            borderRadius: 8,
            color: "#8daac7",
            fontSize: 26,
            fontWeight: 600,
          },
          content.eyebrow,
        ),
        el(
          "div",
          {
            width: textWidth,
            fontSize: titleSize,
            fontWeight: 600,
            lineHeight: 1.15,
            color: "#ffffff",
            display: "block",
            lineClamp: 3,
          },
          content.title,
        ),
        el(
          "div",
          {
            width: textWidth,
            fontSize: 28,
            lineHeight: 1.4,
            color: "#9aa1aa",
            display: "block",
            lineClamp: 2,
          },
          content.description,
        ),
      ]),
      el("div", { display: "flex", alignItems: "center", gap: 22 }, [
        {
          type: "img",
          props: {
            src: avatar,
            width: 72,
            height: 72,
            style: { borderRadius: 36 },
          },
        },
        el("div", { display: "flex", flexDirection: "column" }, [
          el(
            "div",
            { fontSize: 30, fontWeight: 600, color: "#ffffff" },
            content.author,
          ),
          el("div", { fontSize: 24, color: "#8daac7" }, content.role),
        ]),
      ]),
    ],
  );
  const svg = await satori(tree as Parameters<typeof satori>[0], {
    width: OG_WIDTH,
    height: OG_HEIGHT,
    fonts: [
      { name: "IBM Plex Sans", data: regular, weight: 400, style: "normal" },
      { name: "IBM Plex Sans", data: bold, weight: 600, style: "normal" },
    ],
  });
  return sharp(Buffer.from(svg)).png({ compressionLevel: 9 }).toBuffer();
}
